def transform(grid):
    h, w = len(grid), len(grid[0])

    # Most frequent color is the background; the longest contiguous
    # non-background run is the pattern to replicate.
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    pattern = []
    seed_pos = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start > len(pattern):
                pattern = row[start:c]
                seed_pos = {(r, x) for x in range(start, c)}

    # The isolated color marking locations is the most common non-background
    # color not part of the seed pattern.
    nonbg = [(color, n) for color, n in counts.items() if color != bg]
    marker = max(nonbg, key=lambda item: item[1])[0]
    for color, _ in nonbg:
        if color not in pattern and counts[color] >= 1:
            marker = color
            break

    out = [row[:] for row in grid]
    anchor = len(pattern) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r, c) not in seed_pos:
                for k, color in enumerate(pattern):
                    cc = c + k - anchor
                    if 0 <= cc < w:
                        out[r][cc] = color
    return out
